    id: "bulgaria-vrantsa-cities-v2", "sights": {"de": [{"name": "Arheologicheski muzei \"Prof. Mechislav Domaradski\"", "text": "Ein Museum, das archäologische Funde aus der Region Vrantsa und Septemvri ausstellt.", "category": "museum", "coords": [24.129736, 42.210393]}], "hu": [{"name": "Arheologicheski muzei \"Prof. Mechislav Domaradski\"", "text": "A vrancai és szeptemvri régió régészeti leleteit bemutató múzeum.", "category": "museum", "coords": [24.129736, 42.210393]}], "ro": [{"name": "Arheologicheski muzei \"Prof. Mechislav Domaradski\"", "text": "Un muzeu care expune descoperiri arheologice din regiunea Vrața și Septemvri.", "category": "museum", "coords": [24.129736, 42.210393]}], "en": [{"name": "Archaeological Museum", "text": "A museum exhibiting archaeological finds from the Vrantsa and Septemvri region.", "category": "museum", "coords": [24.129736, 42.210393]}]},
