    id: "bulgaria-suvorovo-cities-v2", "sights": {"de": [{"name": "Yazovir Nikolaevka", "text": "Ein großer Stausee in Suworowo, ideal für die Erholung im Freien.", "category": "natural", "coords": [27.687407, 43.370017]}, {"name": "Yazovir Levski", "text": "Ein ruhiger Ort am See in Suworowo, perfekt zum Entspannen.", "category": "natural", "coords": [27.661155, 43.323279]}], "hu": [{"name": "Yazovir Nikolaevka", "text": "Nagy víztározó Szuvorovo közelében, ideális a szabadtéri kikapcsolódáshoz.", "category": "natural", "coords": [27.687407, 43.370017]}, {"name": "Yazovir Levski", "text": "Csendes tóparti hely Szuvorovo területén, tökéletes a pihenésre.", "category": "natural", "coords": [27.661155, 43.323279]}], "ro": [{"name": "Yazovir Nikolaevka", "text": "Un lac de acumulare mare în Suvorovo, ideal pentru recreere în aer liber.", "category": "natural", "coords": [27.687407, 43.370017]}, {"name": "Yazovir Levski", "text": "Un loc liniștit la lac în Suvorovo, perfect pentru relaxare.", "category": "natural", "coords": [27.661155, 43.323279]}], "en": [{"name": "Yazovir Nikolaevka", "text": "A large reservoir in Suvorovo, ideal for outdoor recreation.", "category": "natural", "coords": [27.687407, 43.370017]}, {"name": "Yazovir Levski", "text": "A quiet lakeside spot in Suvorovo, perfect for relaxing.", "category": "natural", "coords": [27.661155, 43.323279]}]},
    type: "city",
